/**
 * Production hosted custody/admission factory (hosted components, installed
 * by the core). Active only when the deployment is fully configured for KMS; any
 * missing or partial setting leaves the default DENY seams in place (fail closed).
 *
 * Deployment settings (secrets unless noted):
 * - KMS_KEY_ARN, AWS_REGION (var), AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY,
 *   AWS_SESSION_TOKEN (optional), KMS_ENVIRONMENT (var: lab|staging|production),
 *   KMS_COLLECTIONS_SHA256 (var): the digest of the bundled allowlist module
 *   (`#hosted-kms-collections`, generated by build-kms-allowlist.mjs), pinned by
 *   the deploy manifest. The allowlist is never inferred from a request.
 *   Staging/production require this module and never read KMS_COLLECTIONS.
 *   Only legacy LAB/local builds accept the transitional secret (equality-only
 *   when a module is bundled); remove that compatibility with those builds.
 *   An allow-all module (`*\n`) is accepted only by a staging/production CP
 *   deployment: SERVICE_KIND (var: hosted|escrow) must be declared and equal the
 *   module's role and the custody role, and no migration binding
 *   (CP_MIGRATION_TOKEN or any LEGACY_* binding) may be present;
 * - CP_URL (var, https), CP_INBOUND_TOKEN: this deployment's control-plane token;
 * - Signed build-release-trust module binds environment/CP/log origins and pins.
 *   CP_ROOTS is optional legacy equality assertion ONLY, never authority.
 * - HOSTED_SIGNERS (optional persisted device-local key trust, 0–16 UUIDs;
 *   service devices have no SAS signers), LOG_URL equals the signed release origin.
 */
import { ControlClient } from "./control.ts";
import { HostedAwsKms } from "./custody/aws-kms.ts";
import { LocalSoftwareKms } from "./custody/local-kms.ts";
import { labStubWrapper } from "./custody-stub.ts";
import { localBuild, localOrigin } from "./local-origin.ts";
import { appReleaseTrust } from "#hosted-release-trust";
import { kmsCollections } from "#hosted-kms-collections";
import { deploymentKmsAllowlist } from "./custody/kms-allowlist.ts";
import type { ReleaseTrust } from "./unconfigured-release-trust.ts";
import { HostedCustody, validHostedSigners, type DevicePublicKeys, type HostedControlPort, type VerifyOriginalGenesis } from "./custody/hosted-custody.ts";
import type { Custody, DeviceKeyWrapper, OpenKeys } from "./seams.ts";

export interface FactoryEnv {
  KMS_KEY_ARN?: string; AWS_REGION?: string; AWS_ACCESS_KEY_ID?: string; AWS_SECRET_ACCESS_KEY?: string;
  AWS_SESSION_TOKEN?: string; KMS_ENVIRONMENT?: string; KMS_COLLECTIONS?: string; KMS_COLLECTIONS_SHA256?: string;
  CP_URL?: string; CP_INBOUND_TOKEN?: string; CP_ROOTS?: string; HOSTED_SIGNERS?: string;
  LOG_URL?: string; LAB?: string; LAB_CUSTODY_WRAP_KEY?: string; LOCAL_KMS_KEY?: string;
  SERVICE_KIND?: string; CP_MIGRATION_TOKEN?: string;
}

/** True when this deployment carries any migration binding: the migration
 * Worker's CP migration token or a legacy-source binding/var. Such a deployment
 * never serves an allow-all KMS module. */
export function migrationDeployment(env: FactoryEnv): boolean {
  return Object.keys(env).some(key => (key === "CP_MIGRATION_TOKEN" || key.startsWith("LEGACY_"))
    && (env as Record<string, unknown>)[key] !== undefined);
}

const list = (s: string | undefined) => (s ?? "").split(",").map((x) => x.trim()).filter(Boolean);

/** Bundled release literals ONLY. No caller-supplied/root/runtime selection.
 * Legacy CP_ROOTS can assert equality, never add/substitute authority. */
export function deploymentRelease(env: FactoryEnv): ReleaseTrust | null {
  const trust = appReleaseTrust();
  if (localBuild() ? trust?.environment !== "local" || !localOrigin(trust.cpOrigin, "local") || !localOrigin(trust.logOrigin, "local")
    : trust?.environment === "local" || env.LOCAL_KMS_KEY !== undefined) return null;
  if (!trust || trust.schema !== "mdbn-app-trust/release/1"
      || trust.environment !== (env.KMS_ENVIRONMENT ?? (env.LAB === "1" ? "lab" : undefined))
      || env.CP_URL !== trust.cpOrigin || env.LOG_URL !== trust.logOrigin
      || !trust.policyPins.length || trust.policyPins.length > (64 << 10)
      || !trust.trustedRoots.length || trust.trustedRoots.length > 64) return null;
  if (env.CP_ROOTS !== undefined) {
    const declared = list(env.CP_ROOTS).sort();
    const bundled = trust.trustedRoots.map(pk => Array.from(pk, b => b.toString(16).padStart(2, "0")).join("")).sort();
    if (declared.length !== bundled.length || declared.some((r, i) => r !== bundled[i])) return null;
  }
  return trust;
}

// No exported registration/setter. Only this actual compiled-release-verified
// factory may bind its newly constructed ControlClient to a deployment origin.
const cppOwnedControls = new WeakMap<ControlClient, string>();
const controlOriginData = ControlClient.prototype.cppClaimOriginData;

/** Actual object provenance + immutable configuration DATA, not permission. */
export function ownedCppControlOrigin(control: ControlClient): string | null {
  const origin = cppOwnedControls.get(control);
  if (!origin) return null;
  try { return controlOriginData.call(control) === origin ? origin : null; }
  catch { return null; }
}

export interface ProductionParts {
  kms: HostedAwsKms | LocalSoftwareKms;
  control: ControlClient;
  roots: Uint8Array[];
  policyPins: Uint8Array;
  signers: string[];
  keyArn: string;
}

/** The configured parts, or null (DENY). Managed escrow generation is staging
 * or production only, authenticated by the bundled release, not a runtime
 * LAB/env assertion. Escrow actor custody (unwrap) is not composed here.
 * Local builds retain their isolated software-KMS path. */
export function productionParts(env: FactoryEnv, fetchImpl: typeof fetch = fetch, role: "hosted" | "escrow" = "hosted"): ProductionParts | null {
  const trust = deploymentRelease(env);
  if ((role !== "hosted" && role !== "escrow") || (role === "escrow" && !localBuild() && trust?.environment !== "staging" && trust?.environment !== "production")) return null;
  const signerText = (env.HOSTED_SIGNERS ?? "").trim();
  // Do not filter malformed empty entries out of a non-empty CSV declaration.
  const signers = signerText === "" ? [] : signerText.split(",").map(x => x.trim());
  if (!env.KMS_KEY_ARN || !env.CP_URL || !env.CP_INBOUND_TOKEN || !trust || !validHostedSigners(signers)) return null;
  if (!localBuild() && (!env.AWS_REGION || !env.AWS_ACCESS_KEY_ID || !env.AWS_SECRET_ACCESS_KEY)) return null;
  const environment = env.KMS_ENVIRONMENT as "lab" | "staging" | "production";
  try {
    // Verified release environment selects policy; staging/production have no
    // runtime-secret fallback, including when Wrangler retains an old binding.
    const collections = deploymentKmsAllowlist(kmsCollections(), env.KMS_COLLECTIONS_SHA256, env.KMS_COLLECTIONS, trust.environment,
      { role, serviceKind: env.SERVICE_KIND, migration: migrationDeployment(env) });
    const kms = localBuild() ? new LocalSoftwareKms(env.KMS_KEY_ARN, env.LOCAL_KMS_KEY ?? "", env.KMS_ENVIRONMENT ?? "", collections) : new HostedAwsKms(
      { keyArn: env.KMS_KEY_ARN, region: env.AWS_REGION!, environment, collections, role },
      () => ({ accessKeyId: env.AWS_ACCESS_KEY_ID!, secretAccessKey: env.AWS_SECRET_ACCESS_KEY!,
        ...(env.AWS_SESSION_TOKEN ? { sessionToken: env.AWS_SESSION_TOKEN } : {}) }),
      fetchImpl,
    );
    const control = new ControlClient({ url: env.CP_URL, token: env.CP_INBOUND_TOKEN, kind: role, environment: trust.environment }, fetchImpl);
    if (controlOriginData.call(control) === trust.cpOrigin) cppOwnedControls.set(control, trust.cpOrigin);
    return { kms, control, roots: trust.trustedRoots.map(pk => new Uint8Array(pk)), policyPins: new Uint8Array(trust.policyPins), signers, keyArn: env.KMS_KEY_ARN };
  } catch {
    return null;
  }
}

/** The core ControlClient as HostedCustody's port: hosted records only. */
export function hostedPort(control: ControlClient): HostedControlPort {
  return {
    async serviceDevice(collection, signal) {
      const r = await control.serviceDevice(collection, signal);
      if (r.kind !== "hosted") throw new Error("custody_invalid_record");
      return { ...r, kind: "hosted" };
    },
    logToken: (device, collection, signal) => control.logToken(device, collection, signal),
    forget: (collection) => control.forget(collection),
  };
}

/** One wrapper selector for the stateless CP bootstrap. Build trust owns the
 * managed environment; LAB flags cannot downgrade staging/production into a stub. */
export function serviceDeviceWrapper(env: FactoryEnv, role: "hosted" | "escrow", fetchImpl: typeof fetch = fetch): DeviceKeyWrapper | null {
  const trust = appReleaseTrust();
  if (env.LAB === "1" && trust && trust.environment !== "lab") return null;
  const parts = productionParts(env, fetchImpl, role);
  if (parts) return { wrapDeviceKeys: (input, signal) => parts.kms.wrapDeviceKeys(input, signal) };
  return env.LAB === "1" && (!env.KMS_ENVIRONMENT || env.KMS_ENVIRONMENT === "lab")
    ? labStubWrapper(role, env.LAB_CUSTODY_WRAP_KEY) : null;
}

/**
 * The per-DO custody: one HostedCustody for this DO's one collection, created on
 * first use with a replica ID persisted in the DO (stable across wakes). Closed on
 * wake replacement/revocation via `close()`.
 */
export class ProductionCustody implements Custody {
  private custody: HostedCustody | null = null;
  /** Single flight: the one creation in progress (no second instance, no waiters
   * beyond callers already holding this promise). */
  private creating: Promise<HostedCustody> | null = null;
  private collection: string | null = null;
  /** Terminal: once closed, nothing is created or handed out again. */
  private closed = false;

  constructor(
    private readonly parts: ProductionParts,
    private readonly replicaId: () => Promise<string>,
    private readonly derive: (secret: Uint8Array) => DevicePublicKeys | null,
    private readonly verifyOriginal: VerifyOriginalGenesis,
    private readonly labRawErrors = false,
  ) {}

  private async get(collection: string): Promise<HostedCustody> {
    if (this.closed || (this.collection && this.collection !== collection)) throw new Error("custody_unavailable");
    if (this.custody) return this.custody;
    this.collection = collection;
    this.creating ??= (async () => {
      const replicaId = await this.replicaId();
      // Closed while the replica ID was read: never create (or hand out) after close.
      if (this.closed) throw new Error("custody_aborted");
      const c = new HostedCustody(
        { collection, replicaId, keyArn: this.parts.keyArn, roots: this.parts.roots, policyPins: this.parts.policyPins, signers: this.parts.signers, labRawErrors: this.labRawErrors },
        hostedPort(this.parts.control), this.parts.kms, this.derive, this.verifyOriginal,
      );
      this.custody = c;
      return c;
    })().finally(() => {
      this.creating = null;
    });
    const c = await this.creating;
    if (this.closed) throw new Error("custody_aborted");
    return c;
  }

  async openSealer(collection: string, signal: AbortSignal): Promise<OpenKeys> {
    const keys = await (await this.get(collection)).openSealer(collection, signal);
    if (this.closed || signal.aborted) {
      keys.zeroize();
      throw new Error("custody_aborted");
    }
    return keys;
  }

  async logToken(collection: string, signal: AbortSignal): Promise<string> {
    const token = await (await this.get(collection)).logToken(collection, signal);
    // Closed (or aborted) while the token was minted: never hand it out.
    if (this.closed || signal.aborted) throw new Error("custody_aborted");
    return token;
  }

  invalidateLogToken(collection: string): void {
    if (this.collection === collection) this.custody?.invalidateLogToken();
  }

  /** Terminal: closes the custody (aborting pending CP/KMS work and wiping keys) and
   * refuses every later or in-flight request. */
  close(): void {
    this.closed = true;
    this.custody?.close();
  }
}
